$('.comments').each(function(i, e) {
  var override = $(e).find('.override-with').html();
  if (override) {
    $(e).find('.text').html(override);
  }
  if ($(e).find('.quote').length) {
    var quote = $(e).find('.quote').html();
    if (quote) {
      $(e).find('.comment-in-quote').html(quote);
    }
  }
});

