from abc import ABC, abstractmethod

class Gender(ABC):
    def __init__(self, name, pronouns):
        self.name = name
        self.pronouns = pronouns

    def introduce(self):
        print(f"I'm {self.name}, a {self.name}.")

    @abstractmethod
    def express(self):
        pass

class Women(Gender):
    def __init__(self):
        super().__init__('woman', {'gender': 'woman', 'pronouns': ['she','her']})

    def express(self):
        print("women are free and empowered.")
